var SOUND_SPEED = 343;
function distanceToDelay(d){ return d/SOUND_SPEED; }
function delayToDistance(t){ return t*SOUND_SPEED; }
function bpmToMs(bpm){ return 60000/bpm; }
function beatDelay(bpm, beats){ return 60000/bpm*beats/1000; }
function sabineRT60(volume, absorption){ return 0.161*volume/absorption; }
var EXPORTS={ SOUND_SPEED:SOUND_SPEED, distanceToDelay:distanceToDelay, delayToDistance:delayToDistance, bpmToMs:bpmToMs, beatDelay:beatDelay, sabineRT60:sabineRT60 };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.DelayForgePure = EXPORTS; }
